const f1='600 16px '+FONT,f2='500 10.5px '+MONO,f3='600 11.5px '+MONO,w=Math.max(textW(f1,name),textW(f2,sub),textW(f3,l1)+18,textW(f3,l2)+18)+26,h=80;
