specs.forEach(s=>{s.level=s.kind==='comp'?s.item.level:null;s.roof=s.kind==='comp'?SH+s.level*lv:0;});
layout(scope,specs,view);
makeBoard(layoutOf(scope));
specs.forEach((sp,i)=>buildItem(sp,i));
