// the nodes inside: small blocks in one row just under the roof; a lane one of them makes starts at its block
const kids=MAP.children.get(c.node),kr=kids.length>1?rT*0.48:0;
kids.forEach((k,j)=>{const a=j/kids.length*Math.PI*2+Math.PI/6,x=Math.sin(a)*kr,z=Math.cos(a)*kr;add(at(new THREE.Mesh(new THREE.BoxGeometry(0.2,0.14,0.2),new THREE.MeshBasicMaterial({color:TH.inner})),x,h-0.32,z),false);it.inner[k]={x:x,z:z};});
// where lanes land on the roof: a spot per port, or the roof's middle when nothing is inside
it.chips={};(sp.node.ports||[]).forEach((pt,i)=>{const a=Math.PI/6+(i%6)*Math.PI/3,o=rT*Math.cos(Math.PI/6)*(0.72-Math.floor(i/6)*0.25);it.chips[pt.name]=kids.length?{x:Math.sin(a)*o,z:Math.cos(a)*o}:{x:0,z:0};});
