const R=sp.rings,a0=rnd(hash(sp.seed))*Math.PI*2;
const flat=(geo,col,x,z)=>{const m=add(new THREE.Mesh(geo.rotateX(-Math.PI/2),new THREE.MeshBasicMaterial({color:col,transparent:true,opacity:0.95,depthWrite:false,side:THREE.DoubleSide})),false);m.position.set(x,0.04,z);return m;};
for(let i=0;i<sp.up;i++){const a=a0+i/sp.up*Math.PI*2;flat(new THREE.CircleGeometry(0.15,14),TH.used,Math.cos(a)*R.rUp,Math.sin(a)*R.rUp);}
